package clientgen

import (
	"bytes"
	"fmt"
	"go/format"
	"io"

	"github.com/dave/jennifer/jen"
)

const (
	// generator header for all generated files.
	codegenHeader = "Code generated by gqlgoclientgen. DO NOT EDIT."

	// hasura graphql client import path.
	hasuraClientPkg = "github.com/hasura/go-graphql-client"

	// backoff package import path.
	backoffPkg = "github.com/cenkalti/backoff/v5"
)

// codeGenerator handles the generation of Go code using jennifer.
type codeGenerator struct {
	pkg  string
	file *jen.File
}

// newCodeGenerator creates a new code generator for a package with the
// default header.
func newCodeGenerator(packageName string) *codeGenerator {
	return newCodeGeneratorWithHeader(packageName, codegenHeader)
}

// newCodeGeneratorWithHeader creates a new code generator for a package with
// a custom DO-NOT-EDIT header line.
func newCodeGeneratorWithHeader(packageName, header string) *codeGenerator {
	file := jen.NewFile(packageName)

	file.HeaderComment(header)
	file.Line()

	// alias the backoff import to avoid the v5 suffix in generated code
	file.ImportAlias(backoffPkg, "backoff")

	return &codeGenerator{
		pkg:  packageName,
		file: file,
	}
}

// WriteToBuffer writes the generated code to a buffer.
func (g *codeGenerator) WriteToBuffer() (*bytes.Buffer, error) {
	buf := &bytes.Buffer{}
	if err := g.file.Render(buf); err != nil {
		return nil, fmt.Errorf("failed to render code: %w", err)
	}

	// format the generated code
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		// if formatting fails, return the unformatted code with the error
		// this helps with debugging generation issues
		return buf, err
	}

	return bytes.NewBuffer(formatted), nil
}

// Render writes the generated, formatted code to a writer.
func (g *codeGenerator) Render(w io.Writer) error {
	buf, err := g.WriteToBuffer()
	if err != nil {
		return err
	}

	_, err = io.Copy(w, buf)

	return err
}
